// Unstable: Lambdas are generally unstable unless remembered or static
@Composable
fun UnstableButton(label: String, onClick: () -> Unit) {
    Button(onClick = onClick) { Text(label) } // May recompose even if label/onClick seem the same
}

// Stable: Primitive types like String are stable
@Composable
fun StableButton(label: String, rememberedOnClick: () -> Unit) {
    Button(onClick = rememberedOnClick) { Text(label) } // More likely to skip recomposition if label/rememberedOnClick instance hasn't changed
}

// Usage
val rememberedAction = remember { { /* Do something */ } }
StableButton(label = "Click Me", rememberedOnClick = rememberedAction)  

